HTML = r'''<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Document Operations Desk</title><style>
:root{font-family:system-ui,sans-serif;color:#e8eef9;background:#101a2e}body{max-width:1100px;margin:36px auto;padding:0 24px}h1{font-size:32px;margin-bottom:8px}.muted{color:#a6b7d4}section{background:#19273f;padding:22px;border:1px solid #344867;border-radius:14px;margin:20px 0}label{display:block;margin:14px 0 6px}input,button{font:inherit;border-radius:7px;border:1px solid #607695;padding:10px}input{background:#101a2e;color:white;max-width:100%;box-sizing:border-box}button{background:#92dac5;color:#102c2a;cursor:pointer;margin:8px 8px 0 0}button:disabled{opacity:.45;cursor:default}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #344867}pre{white-space:pre-wrap;overflow-wrap:anywhere}#message{min-height:24px;color:#ffda9d}a{color:#92dac5}.badge{background:#304663;border-radius:5px;padding:4px 8px}@media(max-width:700px){body{padding:0 12px;margin:18px auto}table{font-size:13px}section{padding:14px}h1{font-size:25px}}
</style><h1>Document Operations Desk</h1><p class="muted">Lokale Dokumentenprüfung · Offline-Referenzprojekt · keine echten Kundendaten</p>
<section><h2>1. Dokument importieren</h2><label for="token">Lokaler Zugangscode</label><input id="token" type="password" autocomplete="off" placeholder="Zugangscode des lokalen Servers">
<label for="key">Eindeutige Importkennung</label><input id="key" value="demo-001" maxlength="80">
<label for="file">Gedrucktes Testdokument (Graustufen-PNG oder PGM)</label><input id="file" type="file" accept=".png,.pgm">
<div><button id="upload">Importieren</button><button id="refresh">Liste aktualisieren</button></div><p class="muted">Unterstützt: aufrechte Großbuchstaben und Ziffern im geprüften Druckbild. Unsichere Erkennung bleibt gesperrt.</p></section>
<p id="message" role="status" aria-live="polite"></p><section><h2>2. Verarbeiten und prüfen</h2><table><thead><tr><th>Import</th><th>Status</th><th>Aktion</th></tr></thead><tbody id="jobs"></tbody></table><div id="summary" aria-live="polite"></div><pre id="recognized" aria-label="Erkannter Text"></pre><details><summary>Technische Prüfdaten</summary><pre id="detail" aria-label="Prüfergebnis"></pre></details></section>
<section><h2>3. Geprüfte Ergebnisse</h2><button id="export">CSV erstellen</button><a id="download" hidden download="documents.csv">CSV herunterladen</a><pre id="exportPreview"></pre></section>
<script>
let busy=false,selected=null;const el=id=>document.getElementById(id);function message(text){el('message').textContent=text}
async function api(method,path,body){const response=await fetch(path,{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+el('token').value},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error||'Anfrage fehlgeschlagen');return data}
function setBusy(value){busy=value;for(const button of document.querySelectorAll('button'))button.disabled=value||button.dataset.unavailable==='true'}
async function perform(fn){if(busy)return;setBusy(true);try{await fn()}catch(e){message(e.message)}finally{setBusy(false)}}
function show(job){selected={id:job.id,version:job.version};el('detail').textContent=JSON.stringify(job,null,2);const fields=job.fields||{};el('summary').textContent='Import: '+job.key+' · Status: '+job.status+' · Typ: '+(job.prediction?.label||'noch unbestimmt')+' · Dokument: '+(fields.documentId||'offen')+(fields.totalMinor!==undefined?' · Betrag: '+(fields.totalMinor/100).toFixed(2)+' '+fields.currency:'');el('recognized').textContent=job.ocr?.text||'Noch kein Erkennungsergebnis';}
async function refresh(){const result=await api('GET','/api/jobs');el('jobs').replaceChildren();for(const job of result.jobs){const row=document.createElement('tr');for(const value of [job.key,job.status]){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}const actions=document.createElement('td');for(const [label,action] of [['Ansehen','inspect'],['Verarbeiten','process'],['Freigeben','approved'],['Ablehnen','rejected']]){const b=document.createElement('button');b.textContent=label;b.disabled=action==='inspect'?false:action==='process'?['approved','rejected','review','needs-review'].includes(job.status):!(selected?.id===job.id&&selected?.version===job.version)||(action==='approved'?job.status!=='review':!['review','needs-review'].includes(job.status));b.dataset.unavailable=String(b.disabled);b.disabled=busy||b.disabled;b.onclick=()=>perform(async()=>{if(action==='inspect'){show(await api('GET','/api/jobs/'+job.id));message('Prüfergebnis geladen: '+job.key);await refresh();return}const updated=await api('POST','/api/jobs/'+job.id+'/'+(action==='process'?'process':'review'),action==='process'?{}:{version:job.version,decision:action});show(updated);message('Gespeichert: '+updated.status);await refresh()});actions.append(b)}row.append(actions);el('jobs').append(row)}}
el('upload').onclick=()=>perform(async()=>{const file=el('file').files[0];if(!file)throw Error('Bitte ein Testdokument auswählen');if(file.size>1200100)throw Error('Datei überschreitet die lokale Größenbegrenzung');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const result=await api('POST','/api/jobs',{key:el('key').value,image:btoa(binary)});message('Import gespeichert: '+result.key);await refresh()});
el('refresh').onclick=()=>perform(async()=>{await refresh();message('Liste aktualisiert')});let previousUrl=null;el('export').onclick=()=>perform(async()=>{const result=await api('GET','/api/export');if(previousUrl)URL.revokeObjectURL(previousUrl);previousUrl=URL.createObjectURL(new Blob([result.csv],{type:'text/csv;charset=utf-8'}));el('download').href=previousUrl;el('download').hidden=false;el('exportPreview').textContent=result.csv;message(result.rows.length+' geprüfte Dokumente exportiert')});
</script></html>'''
